					"layer": "base",
					"keys": "turn E3",
					"name": "detune",
					"range": null,
					"default": null,
					"cc": 14,
					"cc_confidence": "community-verified",
					"note": "small pitch offset between the oscillators, for a thicker sound",
					"source": "https://teenage.engineering/guides/op-xy/synth-engines#prism",
					"firmware_min": null,
					"verified_on": null,
					"confidence": "official"
